from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy


class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        grid = message.message[0].data[1]
        prev_move = message.message[0].data[0]
        move = self.find_best_move(grid, prev_move)
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=move, type='custom')]
        )

    def find_best_move(self, grid, prev_move):
        N = len(grid)
        sqrt_N = int(N ** 0.5)

        def is_valid_move(row, col, num):
            for i in range(N):
                if grid[row][i] == num or grid[i][col] == num:
                    return False
            start_row, start_col = (row // sqrt_N) * sqrt_N, (col // sqrt_N) * sqrt_N
            for i in range(start_row, start_row + sqrt_N):
                for j in range(start_col, start_col + sqrt_N):
                    if grid[i][j] == num:
                        return False
            return True

        def get_possible_moves(prev_move):
            if prev_move is None:
                return [(i, j) for i in range(N) for j in range(N) if grid[i][j] == 0]
            prev_row, prev_col = prev_move[0]
            possible_moves = []
            for i in range(N):
                if grid[prev_row][i] == 0:
                    possible_moves.append((prev_row, i))
                if grid[i][prev_col] == 0:
                    possible_moves.append((i, prev_col))
            return possible_moves

        def evaluate_move(move):
            row, col = move
            possible_nums = [num for num in range(1, N + 1) if is_valid_move(row, col, num)]
            if not possible_nums:
                return None
            best_num = None
            min_opponent_options = float('inf')
            for num in possible_nums:
                new_grid = [row[:] for row in grid]
                new_grid[row][col] = num
                opponent_options = sum(1 for _ in get_possible_moves([(row, col), num]) if is_valid_move(*_, num))
                if opponent_options < min_opponent_options:
                    min_opponent_options = opponent_options
                    best_num = num
            return [(row, col), best_num]

        possible_moves = get_possible_moves(prev_move)
        if not possible_moves:
            return None
        best_move = None
        for move in possible_moves:
            evaluated_move = evaluate_move(move)
            if evaluated_move:
                if best_move is None or evaluated_move[1] < best_move[1]:
                    best_move = evaluated_move
        if best_move is None:
            for i in range(N):
                for j in range(N):
                    if grid[i][j] == 0:
                        evaluated_move = evaluate_move((i, j))
                        if evaluated_move:
                            if best_move is None or evaluated_move[1] < best_move[1]:
                                best_move = evaluated_move
        return best_move

